enum Light { case red, green }
func say(_ l: Light) {
    switch l {
    case .red: print("stop")
    case .green: print("go") } }
say(.green)

import Foundation
switch ProcessInfo().thermalState {
case .nominal, .fair: print("cool")
case .serious, .critical: print("hot")
@unknown default: print("new state")
}

@frozen public enum Bit { case on, off }
func show(_ b: Bit) {
    switch b {
    case .on: print("on")
    case .off: print("off") } }
show(.off)

